def flip(a,ud,lr):
 b=a[::-1] if ud else a
 return [r[::-1] if lr else r for r in b]
def expand(a):
 return [sum((flip(a,i%2==1,j%2==1)[r] for j in range(3)),[]) for i in range(3) for r in range(3)]
