  elif bi==1: x=tr(A,lr=True)
  elif bj==1: x=tr(A,ud=True)
  else: x=tr(A,ud=True,lr=True)
  blocks.append(x)
 for r in range(3): rows.append(sum((x[r] for x in blocks),[]))
